// generated by gemini-3.5-flash-lite for PR #6020 (round 2): gen_21_fixed
// intent: Exercise BON8 binary serialization of a large numeric array to hit the vector sink window logic and ensure all generated bytes match.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json j = nlohmann::json::array();
        for (int i = 0; i < 20000; ++i) {
            j.push_back(i);
        }
        std::vector<uint8_t> v = nlohmann::json::to_bon8(j);
        std::cout << "BON8 size: " << v.size() << "\n";
        if (!v.empty()) {
            std::cout << "BON8 first byte: " << static_cast<int>(v[0]) << "\n";
        }
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << "\n";
    }
    return 0;
}
